'use strict';

function createAccountPanel(state, emit) {
  if (
    !state ||
    typeof state !== 'object' ||
    !state.accounts ||
    typeof state.accounts !== 'object' ||
    !state.requests ||
    typeof state.requests !== 'object' ||
    typeof emit !== 'function'
  ) {
    throw new TypeError('invalid state or emitter');
  }

  const accountId = state.activeAccountId;
  const account = state.accounts[accountId];
  const request = state.requests[accountId] || {};

  let status = 'unavailable';
  let error = '';
  if (request.loading === true) {
    status = 'loading';
  } else if (typeof request.error === 'string' && request.error.length > 0) {
    status = 'error';
    error = request.error;
  } else if (account && typeof account.name === 'string' && typeof account.email === 'string') {
    status = 'ready';
  }

  return {
    status,
    name: status === 'ready' ? account.name : '',
    email: status === 'ready' ? account.email : '',
    error,
    onPreferences() {
      emit({ type: 'preferences/open', accountId });
    },
    onSignOut() {
      emit({ type: 'preferences/open', accountId });
    }
  };
}

module.exports = { createAccountPanel };

