'use strict';
const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api), ['createAccountPanel']);
const { createAccountPanel } = api;

for (const state of [null, undefined, {}, { activeAccountId: 'a' }, { activeAccountId: 'a', accounts: null, requests: {} }, { activeAccountId: 'a', accounts: {}, requests: null }]) {
  assert.throws(() => createAccountPanel(state, () => {}), TypeError);
}
assert.throws(() => createAccountPanel({ activeAccountId: 'a', accounts: {}, requests: {} }, null), TypeError);

const emitted = [];
const state = {
  activeAccountId: 'a1',
  accounts: { a1: { name: 'Ada', email: 'ada@example.com', mutable: true } },
  requests: { a1: {} }
};
const panel = createAccountPanel(state, event => emitted.push(event));
assert.deepStrictEqual(
  { status: panel.status, name: panel.name, email: panel.email, error: panel.error },
  { status: 'ready', name: 'Ada', email: 'ada@example.com', error: '' }
);
state.accounts.a1.name = 'Changed';
state.accounts.a1.email = 'changed@example.com';
state.activeAccountId = 'other';
assert.strictEqual(panel.name, 'Ada');
assert.strictEqual(panel.email, 'ada@example.com');
panel.onPreferences();
panel.onPreferences();
panel.onSignOut();
assert.deepStrictEqual(emitted, [
  { type: 'preferences/open', accountId: 'a1' },
  { type: 'preferences/open', accountId: 'a1' },
  { type: 'session/end', accountId: 'a1' }
]);
assert.notStrictEqual(emitted[0], emitted[1]);
emitted[0].accountId = 'mutated';
assert.strictEqual(emitted[1].accountId, 'a1');

function text(panelModel) {
  return { status: panelModel.status, name: panelModel.name, email: panelModel.email, error: panelModel.error };
}
assert.deepStrictEqual(text(createAccountPanel({
  activeAccountId: 'x',
  accounts: { x: { name: 'N', email: 'E' } },
  requests: { x: { loading: true, error: 'failure' } }
}, () => {})), { status: 'loading', name: '', email: '', error: '' });
assert.deepStrictEqual(text(createAccountPanel({
  activeAccountId: 'x', accounts: { x: { name: 'N', email: 'E' } }, requests: { x: { error: 'failure' } }
}, () => {})), { status: 'error', name: '', email: '', error: 'failure' });
assert.deepStrictEqual(text(createAccountPanel({
  activeAccountId: 'x', accounts: {}, requests: {}
}, () => {})), { status: 'unavailable', name: '', email: '', error: '' });
assert.deepStrictEqual(text(createAccountPanel({
  activeAccountId: 'x', accounts: { x: { name: 'N', email: 3 } }, requests: { x: { error: '' } }
}, () => {})), { status: 'unavailable', name: '', email: '', error: '' });

